content = repo.read("logs/service.log", missing_ok=True)
if content == None:
    return {"exists": False}
lines = content.split("\n")
out = []
for i, ln in enumerate(lines):
    if "ALERT" in ln:
        out.append({
            "line_number": i + 1,
            "prev": lines[i-1] if i > 0 else None,
            "match": ln,
            "next": lines[i+1] if i + 1 < len(lines) else None,
        })
return {"exists": True, "total_lines": len(lines), "matches": out}
